1	package darksafe
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"io"
9		"sort"
10		"strings"
11	)
12	
13	// Reason constants for clusters that cannot enter a release plan.
14	const (
15		ReasonDisabled          = "集群已停用"
16		ReasonExcludeMatched    = "命中排除条件"
17		ReasonIncludeNotMatched = "未命中包含条件"
18	)
19	
20	// LabelCondition is a set of exact key-value matches; all must match.
21	type LabelCondition map[string]string
22	
23	// Cluster is a candidate target for a release.
24	type Cluster struct {
25		ID       string
26		Disabled bool
27		Tags     map[string]string
28	}
29	
30	// ReleasePlanInput describes an application release to plan offline.
31	type ReleasePlanInput struct {
32		App       string
33		Revision  string
34		Image     string
35		BatchSize int
36		Clusters  []Cluster
37		Include   []LabelCondition
38		Exclude   []LabelCondition
39		// SpreadBy, when non-empty, names a cluster tag whose value identifies a
40		// fault domain; each batch then contains at most one cluster per domain.
41		SpreadBy string
42	}
43	
44	// AppInfo identifies the application being released.
45	type AppInfo struct {
46		Name     string `json:"name"`
47		Revision string `json:"revision"`
48		Image    string `json:"image"`
49	}
50	
51	// Batch is a sequentially numbered group of cluster IDs.
52	type Batch struct {
53		Index    int      `json:"index"`
54		Clusters []string `json:"clusters"`
55	}
56	
57	// ExcludedCluster explains why a cluster is not in the plan.
58	type ExcludedCluster struct {
59		ID     string `json:"id"`
60		Reason string `json:"reason"`
61	}
62	
63	// ReleasePlan is the deterministic offline release plan.
64	type ReleasePlan struct {
65		App      AppInfo           `json:"app"`
66		Batches  []Batch           `json:"batches"`
67		Excluded []ExcludedCluster `json:"excluded"`
68	}
69	
70	// ParseReleaseInput reads a release plan document and validates its fields.
71	// Every JSON object in the document — including unknown fields and their
72	// nested objects — must have distinct member names; a name appearing twice
73	// (even with the same value, or via equivalent Unicode escapes) is rejected
74	// before any business validation runs.
75	func ParseReleaseInput(data []byte) (ReleasePlanInput, error) {
76		if err := checkDuplicateMembers(data); err != nil {
77			return ReleasePlanInput{}, err
78		}
79		dec := json.NewDecoder(bytes.NewReader(data))
80		dec.UseNumber()
81		var doc map[string]any
82		if err := dec.Decode(&doc); err != nil {
83			return ReleasePlanInput{}, fmt.Errorf("JSON 格式错误: %w", err)
84		}
85		if dec.More() {
86			return ReleasePlanInput{}, errors.New("JSON 格式错误: 文档包含多余内容")
87		}
88		return buildReleaseInput(doc)
89	}
90	
91	// duplicateMemberError reports a JSON object whose member name appears more
92	// than once. Path is a JSONPath-style location that points at the object
93	// owning the duplicate (the duplicate member name itself is reported
94	// separately in field): "$" for the document root, "$.clusters[1]" for a
95	// cluster, "$.clusters[0].tags" for a tag object,
96	// "$.include[2]" / "$.exclude[1]" for a condition, and "$.foo.bar[0]" for
97	// objects nested inside unknown fields. A member name that is not a plain
98	// identifier is wrapped in brackets around a JSON string, so that characters
99	// in the name can never be read as hierarchy or an array index: a top-level
100	// member "meta.info" is at $["meta.info"] (distinct from the nested object
101	// $.meta.info), "zone[0]" stays one whole name at $["zone[0]"], and names
102	// that are empty or contain quotes, backslashes or control characters are
103	// rendered as decodable JSON strings such as $[""] or $["a\nb"].
104	type duplicateMemberError struct {
105		field string
106		path  string
107	}
108	
109	func (e *duplicateMemberError) Error() string {
110		return fmt.Sprintf("JSON 对象存在重复成员: 字段 %q 重复出现于 %s", e.field, e.path)
111	}
112	
113	// checkDuplicateMembers walks every JSON object in data and rejects objects
114	// with duplicate member names. Names are compared after JSON decoding, so
115	// "env" and "env" are the same name while "env" and "ENV", or
116	// " env" and "env", are different. The first duplicate encountered in file
117	// order is reported: the walk is depth-first in document order, so the
118	// second occurrence that appears earliest wins, regardless of value type.
119	func checkDuplicateMembers(data []byte) error {
120		dec := json.NewDecoder(bytes.NewReader(data))
121		// Numbers are only walked past, never interpreted: UseNumber keeps legal
122		// JSON numbers beyond float64 range (e.g. 1e400) from being turned into an
123		// unmarshal-overflow error here. Whether a number is acceptable for a given
124		// field is decided later by business validation.
125		dec.UseNumber()
126		if err := walkJSONValue(dec, "$"); err != nil {
127			return err
128		}
129		if _, err := dec.Token(); err != io.EOF {
130			if err == nil {
131				return errors.New("JSON 格式错误: 文档包含多余内容")
132			}
133			return fmt.Errorf("JSON 格式错误: %w", err)
134		}
135		return nil
136	}
137	
138	// walkJSONValue reads one complete JSON value whose first token has not been
139	// consumed yet.
140	func walkJSONValue(dec *json.Decoder, path string) error {
141		tok, err := dec.Token()
142		if err != nil {
143			if err == io.EOF {
144				return errors.New("JSON 格式错误: 文档为空")
145			}
146			return fmt.Errorf("JSON 格式错误: %w", err)
147		}
148		return walkJSONValueToken(dec, path, tok)
149	}
150	
151	// walkJSONValueToken reads the remainder of a value given its first token.
152	func walkJSONValueToken(dec *json.Decoder, path string, tok json.Token) error {
153		if d, ok := tok.(json.Delim); ok {
154			switch d {
155			case '{':
156				return walkJSONObject(dec, path)
157			case '[':
158				return walkJSONArray(dec, path)
159			default:
160				return fmt.Errorf("JSON 格式错误: 意外的分隔符 %q", d)
161			}
162		}
163		return nil // scalar value (string, number, bool, null)
164	}
165	
166	func walkJSONObject(dec *json.Decoder, path string) error {
167		seen := make(map[string]struct{})
168		for {
169			tok, err := dec.Token()
170			if err != nil {
171				if err == io.EOF {
172					return errors.New("JSON 格式错误: 对象未闭合")
173				}
174				return fmt.Errorf("JSON 格式错误: %w", err)
175			}
176			if d, ok := tok.(json.Delim); ok {
177				if d == '}' {
178					return nil
179				}
180				return fmt.Errorf("JSON 格式错误: 意外的分隔符 %q", d)
181			}
182			key, ok := tok.(string)
183			if !ok {
184				return errors.New("JSON 格式错误: 对象成员名必须是字符串")
185			}
186			if _, dup := seen[key]; dup {
187				return &duplicateMemberError{field: key, path: path}
188			}
189			seen[key] = struct{}{}
190			vtok, err := dec.Token()
191			if err != nil {
192				if err == io.EOF {
193					return errors.New("JSON 格式错误: 缺少成员值")
194				}
195				return fmt.Errorf("JSON 格式错误: %w", err)
196			}
197			if err := walkJSONValueToken(dec, joinMemberPath(path, key), vtok); err != nil {
198				return err
199			}
200		}
201	}
202	
203	// isSimpleMemberName reports whether key may be written with dot notation:
204	// it must start with an ASCII letter or underscore and contain only ASCII
205	// letters, digits, and underscores afterward.
206	func isSimpleMemberName(key string) bool {
207		if key == "" {
208			return false
209		}
210		for i, r := range key {
211			switch {
212			case r == '_' || ('a' <= r && r <= 'z') || ('A' <= r && r <= 'Z'):
213			case i > 0 && ('0' <= r && r <= '9'):
214			default:
215				return false
216			}
217		}
218		return true
219	}
220	
221	// joinMemberPath extends an object location with one member name. Simple
222	// identifier names keep the existing dot spelling ("$.clusters[0].tags");
223	// every other name is rendered as brackets around a JSON-encoded string, so
224	// the text decodes back to exactly the real member name and none of its
225	// characters can be mistaken for a path separator or array index.
226	func joinMemberPath(path, key string) string {
227		if isSimpleMemberName(key) {
228			return path + "." + key
229		}
230		return path + "[" + jsonEncodePathString(key) + "]"
231	}
232	
233	// jsonEncodePathString renders key as a legal JSON string (including the
234	// surrounding quotes); decoding the result restores key exactly, including
235	// empty names and names containing quotes, backslashes, newlines or other
236	// control characters.
237	func jsonEncodePathString(key string) string {
238		bs, err := json.Marshal(key)
239		if err != nil {
240			// json.Marshal cannot fail for a Go string.
241			panic(fmt.Sprintf("json.Marshal(%q): %v", key, err))
242		}
243		return string(bs)
244	}
245	
246	func walkJSONArray(dec *json.Decoder, path string) error {
247		for i := 0; ; i++ {
248			tok, err := dec.Token()
249			if err != nil {
250				if err == io.EOF {
251					return errors.New("JSON 格式错误: 数组未闭合")
252				}
253				return fmt.Errorf("JSON 格式错误: %w", err)
254			}
255			if d, ok := tok.(json.Delim); ok && d == ']' {
256				return nil
257			}
258			if err := walkJSONValueToken(dec, fmt.Sprintf("%s[%d]", path, i), tok); err != nil {
259				return err
260			}
261		}
262	}
263	
264	func buildReleaseInput(doc map[string]any) (ReleasePlanInput, error) {
265		app, err := requiredString(doc, "app")
266		if err != nil {
267			return ReleasePlanInput{}, err
268		}
269		revision, err := requiredString(doc, "revision")
270		if err != nil {
271			return ReleasePlanInput{}, err
272		}
273		image, err := requiredString(doc, "image")
274		if err != nil {
275			return ReleasePlanInput{}, err
276		}
277		batchSize, err := positiveInt(doc, "batchSize")
278		if err != nil {
279			return ReleasePlanInput{}, err
280		}
281		spreadBy, err := optionalSpreadBy(doc)
282		if err != nil {
283			return ReleasePlanInput{}, err
284		}
285		clusters, err := parseClusters(doc["clusters"])
286		if err != nil {
287			return ReleasePlanInput{}, err
288		}
289		include, err := parseConditions(doc["include"], "include")
290		if err != nil {
291			return ReleasePlanInput{}, err
292		}
293		exclude, err := parseConditions(doc["exclude"], "exclude")
294		if err != nil {
295			return ReleasePlanInput{}, err
296		}
297	
298		return ReleasePlanInput{
299			App:       app,
300			Revision:  revision,
301			Image:     image,
302			BatchSize: batchSize,
303			Clusters:  clusters,
304			Include:   include,
305			Exclude:   exclude,
306			SpreadBy:  spreadBy,
307		}, nil
308	}
309	
310	// optionalSpreadBy reads the optional "spreadBy" field: absent or an empty
311	// string disables fault-domain spreading; a non-string value or a string of
312	// only whitespace is rejected. The tag key is used exactly as written.
313	func optionalSpreadBy(doc map[string]any) (string, error) {
314		v, ok := doc["spreadBy"]
315		if !ok {
316			return "", nil
317		}
318		s, ok := v.(string)
319		if !ok {
320			return "", fmt.Errorf("字段 %q 必须是字符串", "spreadBy")
321		}
322		if err := checkSpreadBy(s); err != nil {
323			return "", err
324		}
325		return s, nil
326	}
327	
328	// checkSpreadBy rejects a spreadBy value that is neither empty nor a usable
329	// tag key: a string of only whitespace can never match a valid tag key.
330	func checkSpreadBy(s string) error {
331		if s != "" && strings.TrimSpace(s) == "" {
332			return fmt.Errorf("字段 %q 不能只含空白", "spreadBy")
333		}
334		return nil
335	}
336	
337	// ValidateReleaseInput checks that a release configuration is well-formed:
338	// app/revision/image are non-empty, batchSize is a positive integer, spreadBy
339	// is empty or a usable tag key (not whitespace-only), cluster
340	// IDs are unique across every candidate (including disabled and filtered-out
341	// clusters), and tag/condition keys are non-empty. Errors name the field and
342	// the position in its list; within a cluster the ID is checked before its
343	// tags, and tag keys are examined in ascending order so repeated calls report
344	// the same error. The input is never mutated. MakeReleasePlan calls this
345	// automatically; library callers may use it to validate without planning.
346	func ValidateReleaseInput(in ReleasePlanInput) error {
347		if strings.TrimSpace(in.App) == "" {
348			return errors.New(`字段 "app" 不能为空或只含空白`)
349		}
350		if strings.TrimSpace(in.Revision) == "" {
351			return errors.New(`字段 "revision" 不能为空或只含空白`)
352		}
353		if strings.TrimSpace(in.Image) == "" {
354			return errors.New(`字段 "image" 不能为空或只含空白`)
355		}
356		if in.BatchSize <= 0 {
357			return errors.New(`字段 "batchSize" 必须是正整数`)
358		}
359		if err := checkSpreadBy(in.SpreadBy); err != nil {
360			return err
361		}
362		ids := newClusterIDSet(len(in.Clusters))
363		for i, c := range in.Clusters {
364			if err := ids.check(i, c.ID); err != nil {
365				return err
366			}
367			if err := validateTagKeys(i, c.Tags); err != nil {
368				return err
369			}
370		}
371		if err := validateConditionKeys("include", in.Include); err != nil {
372			return err
373		}
374		if err := validateConditionKeys("exclude", in.Exclude); err != nil {
375			return err
376		}
377		return nil
378	}
379	
380	// validateTagKeys applies the shared label-key rule to one cluster's tags,
381	// reporting the cluster's position in the candidate list.
382	func validateTagKeys(clusterIndex int, tags map[string]string) error {
383		if hasEmptyLabelKey(tags) {
384			return fmt.Errorf("clusters[%d] 的标签键不能为空", clusterIndex)
385		}
386		return nil
387	}
388	
389	// validateConditionKeys applies the shared condition rules to every condition
390	// in original order, so the first invalid condition is reported.
391	func validateConditionKeys(field string, conds []LabelCondition) error {
392		for i, cond := range conds {
393			if err := validateCondition(field, i, cond); err != nil {
394				return err
395			}
396		}
397		return nil
398	}
399	
400	func requiredString(doc map[string]any, field string) (string, error) {
401		v, ok := doc[field]
402		if !ok {
403			return "", fmt.Errorf("缺少必需字段 %q", field)
404		}
405		s, ok := v.(string)
406		if !ok {
407			return "", fmt.Errorf("字段 %q 必须是字符串", field)
408		}
409		if strings.TrimSpace(s) == "" {
410			return "", fmt.Errorf("字段 %q 不能为空或只含空白", field)
411		}
412		return s, nil
413	}
414	
415	func positiveInt(doc map[string]any, field string) (int, error) {
416		v, ok := doc[field]
417		if !ok {
418			return 0, fmt.Errorf("缺少必需字段 %q", field)
419		}
420		n, ok := v.(json.Number)
421		if !ok {
422			return 0, fmt.Errorf("字段 %q 必须是正整数", field)
423		}
424		i, err := n.Int64()
425		if err != nil || i <= 0 {
426			return 0, fmt.Errorf("字段 %q 必须是正整数", field)
427		}
428		return int(i), nil
429	}
430	
431	func parseClusters(v any) ([]Cluster, error) {
432		if v == nil {
433			return nil, errors.New("缺少必需字段 \"clusters\"")
434		}
435		raw, ok := v.([]any)
436		if !ok {
437			return nil, errors.New("字段 \"clusters\" 必须是数组")
438		}
439		clusters := make([]Cluster, 0, len(raw))
440		ids := newClusterIDSet(len(raw))
441		for i, item := range raw {
442			obj, ok := item.(map[string]any)
443			if !ok {
444				return nil, fmt.Errorf("clusters[%d] 必须是对象", i)
445			}
446			id, err := clusterIDFromJSON(obj, i, ids)
447			if err != nil {
448				return nil, err
449			}
450	
451			disabled := false
452			if dv, present := obj["disabled"]; present {
453				b, ok := dv.(bool)
454				if !ok {
455					return nil, fmt.Errorf("集群 %q 的 \"disabled\" 必须是布尔值", id)
456				}
457				disabled = b
458			}
459	
460			tags := map[string]string{}
461			if tv, present := obj["tags"]; present {
462				tm, ok := tv.(map[string]any)
463				if !ok {
464					return nil, fmt.Errorf("集群 %q 的 \"tags\" 必须是对象", id)
465				}
466				tags, err = labelsFromJSON(tm,
467					func(string) error { return fmt.Errorf("集群 %q 的标签键不能为空", id) },
468					func(k string) error { return fmt.Errorf("集群 %q 的标签 %q 值必须是字符串", id, k) },
469				)
470				if err != nil {
471					return nil, err
472				}
473			}
474	
475			clusters = append(clusters, Cluster{ID: id, Disabled: disabled, Tags: tags})
476		}
477		return clusters, nil
478	}
479	
480	// clusterIDFromJSON reads the "id" member of one candidate object and applies
481	// the shared cluster-identity rule. A missing member or a non-string value is
482	// a JSON decoding problem with its own reason; an empty or duplicate ID is
483	// reported by the shared rule exactly as for a directly constructed config.
484	func clusterIDFromJSON(obj map[string]any, index int, ids *clusterIDSet) (string, error) {
485		v, ok := obj["id"]
486		if !ok {
487			return "", fmt.Errorf("clusters[%d]: 缺少必需字段 %q", index, "id")
488		}
489		id, ok := v.(string)
490		if !ok {
491			return "", fmt.Errorf("clusters[%d]: 字段 %q 必须是字符串", index, "id")
492		}
493		if err := ids.check(index, id); err != nil {
494			return "", err
495		}
496		return id, nil
497	}
498	
499	func parseConditions(v any, field string) ([]LabelCondition, error) {
500		if v == nil {
501			return []LabelCondition{}, nil
502		}
503		raw, ok := v.([]any)
504		if !ok {
505			return nil, fmt.Errorf("字段 %q 必须是条件数组", field)
506		}
507		conds := make([]LabelCondition, 0, len(raw))
508		for i, item := range raw {
509			obj, ok := item.(map[string]any)
510			if !ok {
511				return nil, fmt.Errorf("%s[%d] 必须是对象", field, i)
512			}
513			cond, err := labelsFromJSON(obj,
514				func(string) error { return fmt.Errorf("%s[%d] 的标签键不能为空", field, i) },
515				func(k string) error { return fmt.Errorf("%s[%d] 的标签 %q 值必须是字符串", field, i, k) },
516			)
517			if err != nil {
518				return nil, err
519			}
520			if err := validateCondition(field, i, cond); err != nil {
521				return nil, err
522			}
523			conds = append(conds, cond)
524		}
525		return conds, nil
526	}
527	
528	// MakeReleasePlan selects available clusters, orders them by ID, and splits
529	// them into batches. When SpreadBy names a tag, each batch holds at most one
530	// cluster per value of that tag (its fault domain) and every selected cluster
531	// must carry the tag. It validates the input first and never mutates it.
532	func MakeReleasePlan(in ReleasePlanInput) (ReleasePlan, error) {
533		if err := ValidateReleaseInput(in); err != nil {
534			return ReleasePlan{}, err
535		}
536		if len(in.Clusters) == 0 {
537			return ReleasePlan{}, errors.New("没有可发布的集群：未提供候选集群")
538		}
539	
540		selected := []string{}
541		excluded := []ExcludedCluster{}
542		for _, c := range in.Clusters {
543			switch {
544			case c.Disabled:
545				excluded = append(excluded, ExcludedCluster{ID: c.ID, Reason: ReasonDisabled})
546			case matchesAny(c.Tags, in.Exclude):
547				excluded = append(excluded, ExcludedCluster{ID: c.ID, Reason: ReasonExcludeMatched})
548			case len(in.Include) > 0 && !matchesAny(c.Tags, in.Include):
549				excluded = append(excluded, ExcludedCluster{ID: c.ID, Reason: ReasonIncludeNotMatched})
550			default:
551				selected = append(selected, c.ID)
552			}
553		}
554	
555		sort.Strings(selected)
556		sort.Slice(excluded, func(i, j int) bool { return excluded[i].ID < excluded[j].ID })
557	
558		if len(selected) == 0 {
559			var b strings.Builder
560			b.WriteString("没有符合规则的可用集群，各候选集群未入选原因：")
561			for _, e := range excluded {
562				b.WriteString("\n  ")
563				b.WriteString(e.ID)
564				b.WriteString("：")
565				b.WriteString(e.Reason)
566			}
567			return ReleasePlan{}, errors.New(b.String())
568		}
569	
570		var batches []Batch
571		if in.SpreadBy == "" {
572			batches = chunkBatches(selected, in.BatchSize)
573		} else {
574			domains, err := faultDomains(in.Clusters, selected, in.SpreadBy)
575			if err != nil {
576				return ReleasePlan{}, err
577			}
578			batches = spreadBatches(selected, domains, in.BatchSize)
579		}
580	
581		return ReleasePlan{
582			App:      AppInfo{Name: in.App, Revision: in.Revision, Image: in.Image},
583			Batches:  batches,
584			Excluded: excluded,
585		}, nil
586	}
587	
588	// chunkBatches splits the ascending IDs into batches of at most batchSize.
589	func chunkBatches(selected []string, batchSize int) []Batch {
590		batches := []Batch{}
591		for i := 0; i < len(selected); i += batchSize {
592			end := i + batchSize
593			if end > len(selected) {
594				end = len(selected)
595			}
596			batches = append(batches, Batch{Index: len(batches) + 1, Clusters: selected[i:end]})
597		}
598		return batches
599	}
600	
601	// faultDomains maps every selected cluster ID to the exact value of its
602	// spreadBy tag. A selected cluster missing the tag fails the whole plan;
603	// selected is ascending, so the smallest such ID is reported. An empty
604	// string tag value is a valid fault domain, distinct from a missing tag.
605	func faultDomains(clusters []Cluster, selected []string, spreadBy string) (map[string]string, error) {
606		tagsByID := make(map[string]map[string]string, len(clusters))
607		for _, c := range clusters {
608			tagsByID[c.ID] = c.Tags
609		}
610		domains := make(map[string]string, len(selected))
611		for _, id := range selected {
612			v, ok := tagsByID[id][spreadBy]
613			if !ok {
614				return nil, fmt.Errorf("集群 %q 缺少故障域标签 %q", id, spreadBy)
615			}
616			domains[id] = v
617		}
618		return domains, nil
619	}
620	
621	// spreadBatches packs the ascending IDs into batches of at most batchSize
622	// with at most one cluster per fault domain in each batch. Each batch takes
623	// the smallest still-unscheduled IDs whose domains do not conflict with the
624	// batch; conflicting clusters are deferred to later batches, so a batch may
625	// be short only when no non-conflicting cluster remains. Every ID appears in
626	// exactly one batch and IDs stay ascending within a batch.
627	func spreadBatches(selected []string, domains map[string]string, batchSize int) []Batch {
628		remaining := append([]string(nil), selected...)
629		batches := []Batch{}
630		for len(remaining) > 0 {
631			// The map never holds more entries than there are remaining clusters,
632			// so size it by them — never by batchSize, which is only an upper
633			// bound and may be a huge legal value (e.g. 1e9 meaning "no limit").
634			used := make(map[string]struct{}, min(batchSize, len(remaining)))
635			batch := []string{}
636			deferred := []string{}
637			for _, id := range remaining {
638				d := domains[id]
639				if _, conflict := used[d]; len(batch) < batchSize && !conflict {
640					used[d] = struct{}{}
641					batch = append(batch, id)
642				} else {
643					deferred = append(deferred, id)
644				}
645			}
646			batches = append(batches, Batch{Index: len(batches) + 1, Clusters: batch})
647			remaining = deferred
648		}
649		return batches
650	}
651	
652	func matchesAny(tags map[string]string, conditions []LabelCondition) bool {
653		for _, cond := range conditions {
654			if matchesAll(tags, cond) {
655				return true
656			}
657		}
658		return false
659	}
660	
661	func matchesAll(tags map[string]string, cond LabelCondition) bool {
662		for k, v := range cond {
663			tv, ok := tags[k]
664			if !ok || tv != v {
665				return false
666			}
667		}
668		return true
669	}
