package darksafe

import (
	"fmt"
	"sort"
)

// This file holds the label rules shared by the two ways a release
// configuration can be validated: parsing a JSON document (ParseReleaseInput)
// and validating a directly constructed Go config (ValidateReleaseInput).
//
// The rules themselves: label keys must be non-empty; label values are matched
// exactly as written — an empty string is a valid value and is never trimmed,
// dropped, or case-folded; a condition object must hold at least one entry.
// When one label set or condition has several problems, the first one in
// ascending key order is reported, so repeated calls give the same error.
// Each path keeps its own error wording (cluster identity vs. list position)
// by formatting errors at the call site.

// sortedLabelKeys returns the keys of a label set in ascending order, so both
// validation paths examine keys — and therefore report problems — in the same
// deterministic order.
func sortedLabelKeys[V any](labels map[string]V) []string {
	keys := make([]string, 0, len(labels))
	for k := range labels {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	return keys
}

// hasEmptyLabelKey reports whether the label set contains an empty key. An
// empty key sorts before any other key, so it is always the first problem
// found when keys are examined in ascending order.
func hasEmptyLabelKey[V any](labels map[string]V) bool {
	for _, k := range sortedLabelKeys(labels) {
		if k == "" {
			return true
		}
	}
	return false
}

// validateCondition enforces the shared rules for one include/exclude
// condition: it must contain at least one entry and no empty label keys. The
// error names the field ("include" or "exclude") and the condition's position,
// the wording both the JSON and the Go-config paths already use.
func validateCondition(field string, index int, cond LabelCondition) error {
	if len(cond) == 0 {
		return fmt.Errorf("%s[%d] 不能为空条件对象", field, index)
	}
	if hasEmptyLabelKey(cond) {
		return fmt.Errorf("%s[%d] 的标签键不能为空", field, index)
	}
	return nil
}

// labelsFromJSON validates a decoded JSON object against the shared label
// rules and returns it as a label set: keys must be non-empty and every value
// must be a string, preserved exactly as written. Keys are examined in
// ascending order and the first problem is reported through keyErr (empty key)
// or valueErr (non-string value), which format the error for the caller's
// context — cluster tags or an include/exclude condition.
func labelsFromJSON(obj map[string]any, keyErr, valueErr func(key string) error) (map[string]string, error) {
	labels := make(map[string]string, len(obj))
	for _, k := range sortedLabelKeys(obj) {
		if k == "" {
			return nil, keyErr(k)
		}
		sv, ok := obj[k].(string)
		if !ok {
			return nil, valueErr(k)
		}
		labels[k] = sv
	}
	return labels, nil
}

package darksafe

import (
	"fmt"
	"strings"
)

// This file holds the cluster-identity rule shared by the two ways a release
// configuration can be validated: parsing a JSON document (ParseReleaseInput)
// and validating a directly constructed Go config (ValidateReleaseInput).
//
// The rule itself: a candidate's ID must not be empty or only whitespace, and
// IDs must be unique across every candidate — disabled clusters and clusters
// that include/exclude conditions would filter out still take part, because
// identity is checked before any batching decision. Emptiness is the only
// whitespace-aware test: a legal ID is compared and kept exactly as written,
// so "c-a", "C-A" and " c-a" are three different IDs that are never trimmed,
// merged, or rewritten. Both paths report the same error for the same
// violation: the candidate's position in the input array (from zero) plus the
// empty-ID or duplicate-ID reason.

// clusterIDSet tracks the IDs already seen while candidates are checked in
// input order, so a later occurrence of an ID can be reported at its own
// position.
type clusterIDSet struct {
	seen map[string]struct{}
}

func newClusterIDSet(capacity int) *clusterIDSet {
	return &clusterIDSet{seen: make(map[string]struct{}, capacity)}
}

// check applies the cluster-identity rule to one candidate's ID at position
// index: the ID must not be empty or whitespace-only, and must not repeat an
// earlier candidate's ID. A legal ID is recorded exactly as written.
func (s *clusterIDSet) check(index int, id string) error {
	if strings.TrimSpace(id) == "" {
		return fmt.Errorf("clusters[%d]: 字段 %q 不能为空或只含空白", index, "id")
	}
	if _, dup := s.seen[id]; dup {
		return fmt.Errorf("clusters[%d]: 重复的集群标识 %q", index, id)
	}
	s.seen[id] = struct{}{}
	return nil
}

package darksafe

import (
	"encoding/json"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"testing"
	"unicode/utf16"
)

// parseDupErr parses data and returns the error; it fails the test if no
// error is returned.
func parseDupErr(t *testing.T, data string) error {
	t.Helper()
	_, err := ParseReleaseInput([]byte(data))
	if err == nil {
		t.Fatalf("expected duplicate-member error for %s", data)
	}
	return err
}

// jsonUEsc renders one BMP code point as its JSON Unicode escape spelling,
// e.g. jsonUEsc('e') is the six-character text backslash-u-0-0-6-5. Building
// these at runtime keeps the test source itself free of escape spellings.
func jsonUEsc(r rune) string { return fmt.Sprintf(`\u%04x`, r) }

// jsonEscaped spells every code point of s as a JSON Unicode escape, so
// jsonEscaped("env") names "env" using escapes only.
func jsonEscaped(s string) string {
	var b strings.Builder
	for _, r := range s {
		b.WriteString(jsonUEsc(r))
	}
	return b.String()
}

// jsonSurrogatePair renders a non-BMP code point (r > 0xFFFF) as an escaped
// high/low surrogate pair, e.g. U+1F600 becomes the 12-character escape text.
func jsonSurrogatePair(r rune) string {
	hi, lo := utf16.EncodeRune(r)
	return fmt.Sprintf(`\u%04x\u%04x`, hi, lo)
}

func TestParse_DuplicateMemberRejectedEverywhere(t *testing.T) {
	base := `"app":"a","revision":"r","image":"i","batchSize":1`
	cases := []struct {
		name      string
		body      string // JSON body without outer braces
		wantField string
		wantPath  string
	}{
		{
			name:      "top-level app",
			body:      `"app":"a","app":"b","revision":"r","image":"i","batchSize":1,"clusters":[]`,
			wantField: "app",
			wantPath:  "$",
		},
		{
			name:      "top-level batchSize",
			body:      `"app":"a","revision":"r","image":"i","batchSize":1,"batchSize":2,"clusters":[]`,
			wantField: "batchSize",
			wantPath:  "$",
		},
		{
			name:      "cluster disabled",
			body:      base + `,"clusters":[{"id":"x","disabled":true,"disabled":false}]`,
			wantField: "disabled",
			wantPath:  "$.clusters[0]",
		},
		{
			name:      "cluster id",
			body:      base + `,"clusters":[{"id":"x","id":"y"}]`,
			wantField: "id",
			wantPath:  "$.clusters[0]",
		},
		{
			name:      "second cluster",
			body:      base + `,"clusters":[{"id":"a"},{"id":"b","disabled":false,"disabled":true}]`,
			wantField: "disabled",
			wantPath:  "$.clusters[1]",
		},
		{
			name:      "tags",
			body:      base + `,"clusters":[{"id":"x","tags":{"env":"prod","env":"dev"}}]`,
			wantField: "env",
			wantPath:  "$.clusters[0].tags",
		},
		{
			name:      "include condition",
			body:      base + `,"clusters":[],"include":[{"env":"prod","env":"dev"}]`,
			wantField: "env",
			wantPath:  "$.include[0]",
		},
		{
			name:      "exclude condition",
			body:      base + `,"clusters":[],"exclude":[{"region":"us","region":"eu"}]`,
			wantField: "region",
			wantPath:  "$.exclude[0]",
		},
		{
			name:      "second include condition",
			body:      base + `,"clusters":[],"include":[{"env":"prod"},{"env":"dev","env":"staging"}]`,
			wantField: "env",
			wantPath:  "$.include[1]",
		},
		{
			name:      "unknown field nested object",
			body:      base + `,"clusters":[],"meta":{"x":1,"x":2}`,
			wantField: "x",
			wantPath:  "$.meta",
		},
		{
			name:      "unknown field array of objects",
			body:      base + `,"clusters":[],"items":[{"y":1,"y":2}]`,
			wantField: "y",
			wantPath:  "$.items[0]",
		},
		{
			name:      "unknown field deep nesting",
			body:      base + `,"clusters":[],"a":{"b":{"c":[{"z":1,"z":2}]}}`,
			wantField: "z",
			wantPath:  "$.a.b.c[0]",
		},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			err := parseDupErr(t, "{"+tc.body+"}")
			msg := err.Error()
			if !strings.Contains(msg, tc.wantField) {
				t.Fatalf("error %q does not name field %q", msg, tc.wantField)
			}
			if !strings.Contains(msg, tc.wantPath) {
				t.Fatalf("error %q does not contain path %q", msg, tc.wantPath)
			}
		})
	}
}

func TestParse_DuplicateRejectedRegardlessOfValues(t *testing.T) {
	base := `"app":"a","revision":"r","image":"i","batchSize":1`
	// Same value twice must still be rejected.
	for _, val := range []string{`true`, `false`, `null`, `1`, `1.5`, `"str"`, `[1,2]`, `{"k":"v"}`} {
		t.Run("same value "+val, func(t *testing.T) {
			body := `{"id":"x","tags":{"env":` + val + `,"env":` + val + `}}`
			err := parseDupErr(t, `{`+base+`,"clusters":[`+body+`]}`)
			if !strings.Contains(err.Error(), "env") {
				t.Fatalf("expected field name in %q", err)
			}
		})
	}
	// Different value types on either side must be rejected.
	pairs := [][2]string{
		{`1`, `true`},
		{`"a"`, `null`},
		{`[]`, `{}`},
		{`false`, `"false"`},
	}
	for _, p := range pairs {
		t.Run("mixed "+p[0]+" "+p[1], func(t *testing.T) {
			body := `{"id":"x","tags":{"env":` + p[0] + `,"env":` + p[1] + `}}`
			err := parseDupErr(t, `{`+base+`,"clusters":[`+body+`]}`)
			if !strings.Contains(err.Error(), "env") {
				t.Fatalf("expected field name in %q", err)
			}
		})
	}
}

