// nothing — when they are absent or not hex, leaving the format error to the
// decoder.
func (s *strictTextScanner) hex4() (rune, bool) {
	if s.pos+4 > len(s.data) {
		return 0, false
	}
	var v rune
	for i := 0; i < 4; i++ {
		c := s.data[s.pos+i]
