package main

import (
	"encoding/json"
	"fmt"
	"math/rand"
	"os"

	"github.com/asdhoaiqqq/darksafe-access/darksafe"
)

// randomJSON generates structurally valid JSON docs (values only), then we
// verify: if encoding/json accepts it, ParseReleaseInput must not fail with
// a strict-text error (it may fail with business errors, which is fine).
func randString(r *rand.Rand) string {
	n := r.Intn(8)
	out := []byte{'"'}
	for i := 0; i < n; i++ {
		switch r.Intn(6) {
		case 0:
			out = append(out, []byte(fmt.Sprintf("%c", 'a'+r.Intn(26)))...)
		case 1: // legal multibyte UTF-8 incl. literal U+FFFD and non-BMP
			out = append(out, []byte(string([]rune{[]rune("中😀�é")[r.Intn(4)]}))...)
		case 2: // escapes
			out = append(out, []byte([]string{`\n`, `\t`, `\"`, `\\`, `\/`, `\b`, `\f`, `\r`}[r.Intn(8)])...)
		case 3: // BMP \u escape
			out = append(out, []byte(fmt.Sprintf(`\u%04x`, 0x20+r.Intn(0xD7FF-0x20)))...)
		case 4: // surrogate pair
			hi := 0xD800 + r.Intn(0x400)
			lo := 0xDC00 + r.Intn(0x400)
			out = append(out, []byte(fmt.Sprintf(`\u%04x\u%04x`, hi, lo))...)
		case 5: // escaped literal backslash + uD800 (ordinary text)
			out = append(out, []byte(`\\uD800`)...)
		}
	}
	return string(append(out, '"'))
}

func randValue(r *rand.Rand, depth int) string {
	if depth > 4 {
		return randString(r)
	}
	switch r.Intn(7) {
	case 0:
		return randString(r)
	case 1:
		return fmt.Sprintf("%d", r.Intn(1000)-500)
	case 2:
		return []string{"true", "false", "null"}[r.Intn(3)]
	case 3:
		return fmt.Sprintf("%d.%de%d", r.Intn(100), r.Intn(100), r.Intn(10))
	case 4: // array
		s := "["
		for i := 0; i < r.Intn(4); i++ {
			if i > 0 {
				s += ","
			}
			s += randValue(r, depth+1)
		}
		return s + "]"
	default: // object
		s := "{"
		for i := 0; i < r.Intn(4); i++ {
			if i > 0 {
				s += ","
			}
			s += randString(r) + ":" + randValue(r, depth+1)
		}
		return s + "}"
	}
}

func main() {
	r := rand.New(rand.NewSource(1))
	bad := 0
	for i := 0; i < 200000; i++ {
		doc := randValue(r, 0)
		if !json.Valid([]byte(doc)) {
			fmt.Println("generator produced invalid JSON:", doc)
			os.Exit(1)
		}
		_, err := darksafe.ParseReleaseInput([]byte(doc))
		if err == nil {
			continue
		}
		msg := err.Error()
		if contains(msg, "UTF-8") || contains(msg, "未配对") {
			fmt.Printf("FALSE POSITIVE on %s: %v\n", doc, err)
			bad++
			if bad > 5 {
				os.Exit(1)
			}
		}
	}
	if bad > 0 {
		os.Exit(1)
	}
	fmt.Println("no false positives on 200000 valid docs")
}

func contains(s, sub string) bool {
	return len(s) >= len(sub) && (func() bool {
		for i := 0; i+len(sub) <= len(s); i++ {
			if s[i:i+len(sub)] == sub {
				return true
			}
		}
		return false
	})()
}
EOF
